def sets():
    t = Translation('sets-and-relations', 'Теория множеств и диаграммы Венна')
    t.lesson('sets-membership-lesson', 'sets-membership', 'Элемент и подмножество', [
        'Множество состоит из элементов. a∈A означает, что a принадлежит A, a∉A — не принадлежит. Повторная запись элемента не создаёт нового: {1,1,2}={1,2}.',
        'A⊆B означает, что все элементы A принадлежат B; допускается A=B. Для собственного подмножества используется запись A⊊B.',
        '∅ — пустое множество, в нём нет элементов. А {∅} содержит один элемент — само пустое множество.',
        'У множества из n различных элементов есть 2ⁿ подмножеств, включая ∅ и само множество.',
        'Условие «Все собаки — животные» означает, что множество собак является подмножеством животных. Если Рекс — собака, то он животное; обратный вывод необязателен.'
    ], 'Перечислите все подмножества A={p,q}.',
        ['Пустое подмножество: ∅.', 'Одноэлементные: {p}, {q}; двухэлементное: {p,q}.', 'Всего 4=2².'], '∅, {p}, {q}, {p,q}')
    t.lesson('sets-operations-lesson', 'sets-operations', 'Объединение, пересечение и разность', [
        'A∪B — все элементы, принадлежащие A или B. Каждый элемент записывается один раз. A∪A=A.',
        'A∩B — общие элементы обоих множеств. A∩A=A, A∩∅=∅.',
        'A∖B — элементы A, не принадлежащие B. A∖B и B∖A обычно не равны; порядок множеств важен.',
        'В программировании set.intersection возвращает общие элементы, union — объединение, difference — разность. Здесь важен факт принадлежности, а не порядок элементов.'
    ], 'Для A={1,2,4}, B={2,3} найдите A∪B, A∩B и A∖B.',
        ['Все различные элементы: {1,2,3,4}.', 'Общий элемент: {2}.', 'После удаления из A элементов B остаётся {1,4}.'], '{1,2,3,4}; {2}; {1,4}')
    t.lesson('sets-complement-lesson', 'sets-complement', 'Универсальное множество и дополнение', [
        'Универсальное множество U содержит все рассматриваемые в задаче элементы. Дополнение A равно A′=U∖A; без указания U дополнение не определено однозначно.',
        'A′ содержит элементы U, не принадлежащие A. Элементы вне U не включаются.',
        'При одном и том же U: (A′)′=A, A∪A′=U и A∩A′=∅.',
        'Например, при U={a,b,c}, A={b} имеем A′={a,c}. Повторное дополнение возвращает {b}.'
    ], 'При U={1,2,3,4,5,6}, A={1,3,5} найдите A′.',
        ['Проверим каждый элемент U.', 'Исключаем 1,3,5 из A; остаются 2,4,6.'], '{2,4,6}')
    t.lesson('sets-venn-lesson', 'sets-venn', 'Области диаграммы Венна', [
        'Для двух кругов U делится на четыре непересекающиеся области: только A, A∩B, только B и область вне обоих кругов.',
        'Число элементов A равно сумме чисел в области только A и в общей области. Для B — аналогично.',
        'A∪B охватывает области только A, пересечение и только B. Общая область учитывается один раз.',
        'Заштрихованная часть A, не общая с B, — это A∖B. Диаграмму также можно описать текстом, указав числа элементов в непересекающихся областях.'
    ], 'В области только A — 4 элемента, в пересечении — 3, только B — 2. Найдите |A| и |A∪B|.',
        ['Круг A: 4+3=7.', 'Объединение состоит из трёх внутренних областей: 4+3+2=9.'], '|A|=7; |A∪B|=9')
    t.lesson('sets-counting-lesson', 'sets-counting', 'Число элементов и двойной подсчёт', [
        '|A| обозначает число различных элементов A. Для двух множеств |A∪B|=|A|+|B|−|A∩B|.',
        'Пересечение вычитается, потому что оно посчитано дважды: в |A| и в |B|. Чтобы учесть его один раз, его вычитают один раз.',
        'Число элементов вне обоих множеств равно |U|−|A∪B|. Если неизвестно пересечение, то |A∩B|=|A|+|B|−|A∪B|.',
        'Числа должны соответствовать условию: пересечение не может быть больше любого из множеств, а объединение — больше U.'
    ], 'Из 30 человек 18 входят в A, 15 — в B, а 7 — в обе группы. Сколько не входит ни в одну?',
        ['Объединение: 18+15−7=26.', 'Вне групп: 30−26=4.'], '4')
    q = t.question
    q('sets-practice-01', 'Сколько всего подмножеств у A={a,b}?', 'Есть подмножества ∅, {a}, {b}, {a,b}.|Всего 2²=4.', 'Учтите пустое множество и само A.', 'Не приравнивайте число подмножеств к числу элементов.')
    q('sets-practice-02', 'Сколько различных элементов в множестве {1,1,2,3}?', 'Повторная 1 не является новым элементом.|Различные элементы 1,2,3: всего 3.', 'Одинаковые элементы считайте один раз.', 'Множество — не список; повторы не считаются отдельно.')
    q('sets-practice-03', 'При A={1,2,3,4,5}, B={4,5,6,7} выберите A∪B.', 'Берём все различные элементы обоих множеств.|Объединение {1,2,3,4,5,6,7}.', 'Не записывайте общие элементы повторно.', 'Объединение состоит не только из общих элементов.', ['Это B∖A.', 'Верно. Объединение {1,2,3,4,5,6,7}.', 'Это пересечение.', 'Это A∖B.'])
